import{_ as s,a0 as i,w as a,s as r,I as n,x as e,a1 as p,A as o,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"如何從 Ubuntu 22.04 LTS 升級到 22.10 | LCTT x X-CMD","titleTemplate":false,"description":"如何從 Ubuntu 22.04 LTS 升級到 22.10 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從 Ubuntu 22.04 LTS 升級到 22.10 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從 Ubuntu 22.04 LTS 升級到 22.10 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221021.1 ⭐️  How to Upgrade to Ubuntu 22.10 From 22.04 LTS (Jammy to Kinetic)","title":"如何從 Ubuntu 22.04 LTS 升級到 22.10","tag":"202211","desc":""},"relativePath":"202211/20221021.1 ⭐️  How to Upgrade to Ubuntu 22.10 From 22.04 LTS (Jammy to Kinetic).md","filePath":"[post].md"}'),d={name:"202211/20221021.1 ⭐️  How to Upgrade to Ubuntu 22.10 From 22.04 LTS (Jammy to Kinetic).md"};function b(m,t,g,h,w,f){const u=i("Link");return a(),r("div",null,[t[24]||(t[24]=n("h1",{id:"如何從-ubuntu-22-04-lts-升級到-22-10",tabindex:"-1"},[e("如何從 Ubuntu 22.04 LTS 升級到 22.10 "),n("a",{class:"header-anchor",href:"#如何從-ubuntu-22-04-lts-升級到-22-10","aria-label":"Permalink to “如何從 Ubuntu 22.04 LTS 升級到 22.10”"},"​")],-1)),t[25]||(t[25]=n("blockquote",null,[n("p",null,"這裏是如何將你當前的 Ubuntu 22.04 LTS Jammy Jellyfish 升級到 Ubuntu 22.10 Kinetic Kudu 的步驟。")],-1)),n("p",null,[t[1]||(t[1]=e("始終停留在長期支持的發佈版本，這是金科玉律。因為，先前的 ",-1)),p(u,{href:"https://www.debugpoint.com/ubuntu-22-04-review/"},{default:o(()=>[...t[0]||(t[0]=[e("Ubuntu 22.04 LTS",-1)])]),_:1}),t[2]||(t[2]=e(" Jammy Jellyfish 將被支持到 2027 年 4 月。這是一段很長的時間。",-1))]),t[26]||(t[26]=n("p",null,"此外，LTS 版本超級穩定。它們很少損壞並變得不穩定。因此，如果你在筆記本電腦/台式機電腦或服務器上安裝使用 LTS 版本，保持使用它。",-1)),n("p",null,[t[4]||(t[4]=e("然而，如果你想要最新的內核、GNOME 43 和 Pipewire 之類的最新技術 – 你可能會想完成版本跳級，並升級到 ",-1)),p(u,{href:"https://www.debugpoint.com/ubuntu-22-10/"},{default:o(()=>[...t[3]||(t[3]=[e("Ubuntu 22.10 Kinetic Kudu",-1)])]),_:1}),t[5]||(t[5]=e("。",-1))]),t[27]||(t[27]=l(`<p>這裏是如何做的方法。</p><h3 id="升級-ubuntu-22-04-lts-到-ubuntu-22-10" tabindex="-1">升級 Ubuntu 22.04 LTS 到 Ubuntu 22.10 <a class="header-anchor" href="#升級-ubuntu-22-04-lts-到-ubuntu-22-10" aria-label="Permalink to “升級 Ubuntu 22.04 LTS 到 Ubuntu 22.10”">​</a></h3><p><strong>注意</strong>：我希望你沒有運行去年 10 月份發佈的 Ubuntu 21.10 Impish Indri 。因為它已經不被支持。但是鑑於某些原因，你正在運行它，我建議你直接重新安裝 22.10 。或者，先升級到 22.04 ，再升級到 22.10 。</p><h4 id="在你升級前" tabindex="-1">在你升級前 <a class="header-anchor" href="#在你升級前" aria-label="Permalink to “在你升級前”">​</a></h4><p>在你升級前，做一些內務整理。這是非常重要的。</p><ul><li>備份你的 <code>/home</code>、/<code>downloads</code> 和其它的文件到 USB 驅動器或任意獨立的分區，以防升級失敗。</li><li>如果你隨着時間的流逝而添加了一些額外的 PPA ，確保將它們記錄下來。雖然，在升級過程開始前，升級過程將禁用 PPA 。而在升級完成後，確保手動啓用 PPA 。</li><li>記錄並禁用所有的 GNOME 擴展。如果開發人員沒有按照 GNOME 版本進行更新，那麼擴展在升級後將會損壞。</li><li>家中常備一個現場 USB 磁盤。</li></ul><h4 id="升級步驟" tabindex="-1">升級步驟 <a class="header-anchor" href="#升級步驟" aria-label="Permalink to “升級步驟”">​</a></h4><p>打開 “<ruby>軟件包和更新<rt>Software &amp; Update</rt></ruby>” 。</p><p>轉到 “<ruby>更新<rt>Updates</rt></ruby>” 標籤頁。</p><p>轉到 “<ruby>通知我新的 Ubuntu 版本<rt>Notify me of a new Ubuntu version</rt></ruby>”，選擇並將其更改為 “<ruby>任意新的版本<rt>For any new version</rt></ruby>”。</p><p>這將告訴軟件包管理器來查找 Ubuntu 22.10 發佈版本的詳細信息。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/Make-sure-to-change-the-option-for-new-Ubuntu-22.10-release.jpg" alt="Make sure to change the option for new Ubuntu 22.10 release"></p><p>打開一個終端，並運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt upgrade</span></span></code></pre></div><p>或者，你也可以打開軟件包更新程序。安裝所有的準備就緒的軟件包。</p><p>在兩個命令完成後，打開軟件包更新。你將會看到一個升級到 Ubuntu 22.10 的提示（如下圖所示）。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/New-version-update-prompt-from-the-GUI-method2.jpg" alt="New version update prompt from the GUI method"></p><p>現在，單擊 “<ruby>升級<rt>Upgrade</rt></ruby>” 按鈕，並按照屏幕上的説明進行操作。升級過程需要一些時間，因此，要耐心等待，直至升級完成。確保在整個升級過程中有穩定的互聯網鏈接。</p><p>如果你尚未獲得更新，請等待一、兩天後再次嘗試。</p><p>如果你沒有看到上述提示，手動重新啓動一次系統。並再次添加嘗試。</p><h4 id="通過終端" tabindex="-1">通過終端 <a class="header-anchor" href="#通過終端" aria-label="Permalink to “通過終端”">​</a></h4><p>在終端中通過 nano 文件編輯器打開下面的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano /etc/update-manager/release-upgrades</span></span></code></pre></div><p>將 <code>Prompt=LTS</code> 更改為 <code>Prompt=normal</code> 。注意：如果你已經如上所述將更新標籤頁更改為 “<ruby>任意新的版本<rt>For any new version</rt></ruby>” ，那麼這個文件應該已經更新了。但是，要驗證它一次。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/Change-the-release-upgrade-file.jpg" alt="Change the release upgrade file"></p><p>分別按下組合鍵 <code>CTRL+O</code> 和組合鍵 <code>CTRL+X</code> 來保存和退出。</p><p>最後，你也可以運行下面的命令來從終端中強制升級過程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo do-release-upgrade -c</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/New-version-update-prompt-from-the-terminal-method.jpg" alt="New version update prompt from the terminal method"></p><p>升級過程需要花費一些時間（最少半個小時，上不封頂），這主要取決於你的互聯網連接和硬件。直至等到其完成。在完成後，重新啓動並享受 Ubuntu 22.10 Kinetic Kudu.</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/Upgrade-is-in-progress.jpg" alt="Upgrade is in progress"></p>`,31)),n("p",null,[t[7]||(t[7]=e("在升級過程進行時，看看我們 ",-1)),p(u,{href:"https://www.debugpoint.com/tag/ubuntu-22-10"},{default:o(()=>[...t[6]||(t[6]=[e("不久前發佈的關於 Ubuntu 22.10",-1)])]),_:1}),t[8]||(t[8]=e(" 的精彩文章。",-1))]),t[28]||(t[28]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),p(u,{href:"https://www.debugpoint.com/upgrade-ubuntu-22-04-22-10/"},{default:o(()=>[...t[9]||(t[9]=[e("https://www.debugpoint.com/upgrade-ubuntu-22-04-22-10/",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("作者：",-1)),p(u,{href:"https://www.debugpoint.com/author/admin1/"},{default:o(()=>[...t[11]||(t[11]=[e("Arindam",-1)])]),_:1}),t[16]||(t[16]=e(" 選題：",-1)),p(u,{href:"https://github.com/lkxed"},{default:o(()=>[...t[12]||(t[12]=[e("lkxed",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),p(u,{href:"https://github.com/robsean"},{default:o(()=>[...t[13]||(t[13]=[e("robsean",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),p(u,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("本文由 ",-1)),p(u,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),p(u,{href:"https://linux.cn/"},{default:o(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const y=s(d,[["render",b]]);export{U as __pageData,y as default};
